exercises.solutionCode:
String classifyGrade(int score) {
  if (score >= 90) {
    return 'A';
  } else if (score >= 80) {
    return 'B';
  } else if (score >= 70) {
    return 'C';
  } else if (score >= 60) {
    return 'D';
  } else {
    return 'F';
  }
}

void main() {
  print(classifyGrade(95));
  print(classifyGrade(73));
  print(classifyGrade(55));
}

